package ocr

import (
	"bufio"
	"encoding/json"
	"os"
	"strings"
	"testing"
)

// goldenCase is one row of testdata/js_ocr_golden.jsonl, generated by running
// the legacy JavaScript cleanOCRText and parseWordsFromText over each input.
type goldenCase struct {
	Input   string `json:"input"`
	Cleaned string `json:"cleaned"`
	Words   []Word `json:"words"`
}

func loadGolden(t *testing.T) []goldenCase {
	t.Helper()
	file, err := os.Open("testdata/js_ocr_golden.jsonl")
	if err != nil {
		t.Fatalf("open golden fixture: %v", err)
	}
	defer file.Close()

	var cases []goldenCase
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 1<<20), 1<<20)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		var c goldenCase
		if err := json.Unmarshal([]byte(line), &c); err != nil {
			t.Fatalf("bad golden line: %v", err)
		}
		cases = append(cases, c)
	}
	if err := scanner.Err(); err != nil {
		t.Fatal(err)
	}
	if len(cases) == 0 {
		t.Fatal("golden fixture is empty")
	}
	return cases
}

// fabricatedSentinels lists the inputs where the legacy word splitter differed
// on purpose: it only suppressed the exact string "NO TEXT FOUND", so the
// prompt's own "NO TEXT" answer came back as two words that are not on the
// image. Everything else must match byte for byte.
var fabricatedSentinels = map[string]bool{
	"NO TEXT": true,
	"no text": true,
}

func TestLegacyJavaScriptParity(t *testing.T) {
	cases := loadGolden(t)

	for _, c := range cases {
		name := c.Input
		if len(name) > 40 {
			name = name[:40]
		}
		name = strings.ReplaceAll(name, "\n", "\\n")
		if name == "" {
			name = "(empty)"
		}

		t.Run(name, func(t *testing.T) {
			if got := Clean(c.Input); got != c.Cleaned {
				t.Errorf("Clean mismatch\n input:  %q\n got:    %q\nlegacy: %q", c.Input, got, c.Cleaned)
			}

			got := BuildResult(c.Input)
			if fabricatedSentinels[got.Text] {
				if len(got.Words) != 0 {
					t.Errorf("sentinel %q was split into %v, want no words", got.Text, got.Words)
				}
				if len(c.Words) == 0 {
					t.Errorf("fixture expected the legacy build to fabricate words for %q", got.Text)
				}
				return
			}
			if len(got.Words) != len(c.Words) {
				t.Fatalf("word count = %d %v, legacy produced %d %v", len(got.Words), got.Words, len(c.Words), c.Words)
			}
			for i := range c.Words {
				if got.Words[i] != c.Words[i] {
					t.Errorf("words[%d] = %+v, legacy %+v", i, got.Words[i], c.Words[i])
				}
			}
		})
	}
}

// The fixture must keep covering the cases that historically broke: multiline
// Bengali/English ID-card output and every markdown artifact form.
func TestGoldenFixtureCoversImportantShapes(t *testing.T) {
	cases := loadGolden(t)
	needles := []string{
		"বাংলাদেশ",                  // mixed-script line
		"```",                       // fenced block
		"**",                        // bold marker
		"NO TEXT",                   // the prompt's own no-result answer
		"The text in the image is:", // preamble
	}
	for _, needle := range needles {
		found := false
		for _, c := range cases {
			if strings.Contains(c.Input, needle) {
				found = true
				break
			}
		}
		if !found {
			t.Errorf("golden fixture no longer covers %q", needle)
		}
	}
}
